import assert from 'node:assert/strict';
import { Router } from './src/http/router.ts';
import { orderRoutes } from './src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from './src/orders/integration/order-store.ts';
const alice={authorization:'Bearer alice-token'};
function setup(status='pending',customerId='alice') {
 const orders=new InMemoryOrderStore([{id:'o1',customerId,status,items:['sku']}]);
 const sessions={lookup:t=>new Map([['alice-token',{id:'alice'}],['bob-token',{id:'bob'}]]).get(t)};
 return {orders,router:orderRoutes(new Router(),{orders,sessions})};
}
for(const [label,headers,owner,expected] of [
 ['owner',alice,'alice',200],['unauthenticated',{},'alice',401],['invalid token',{authorization:'Bearer invalid'},'alice',401],['malformed auth',{authorization:'Basic alice-token'},'alice',401],['other customer',alice,'bob',404]
]){
 const {orders,router}=setup('pending',owner); const before=orders.all();
 const res=router.handle({method:'POST',path:'/orders/o1/cancel',headers});
 assert.equal(res.status,expected);
 if(expected===200) assert.equal(orders.get('o1').status,'cancelled'); else assert.deepEqual(orders.all(),before);
 console.log(label,res.status,'state verified');
}
for(const status of ['shipped','cancelled']){
